  for(var v2=0;v2<pvn;v2++){var pa=provSorted[v2].answers||{};var cnt=provCounts[provSorted[v2].id]||0;pvHtml+=rowItem(h(pa.full_name||'Provider'),h(labelFor(roleMap,pa.role)),'<span class="chip">'+cnt+(cnt===1?' appt':' appts')+'</span>');}
